                if g[i][j] and not seen[i][j]:
                    stack=[(i,j)]; seen[i][j]=True
                    while stack:
                        r,c=stack.pop(); cid[r][c]=k
                        for dr in(-1,0,1):
                            for dc in(-1,0,1):
                                nr,nc=r+dr,c+dc
                                if 0<=nr<h and 0<=nc<w and g[nr][nc] and not seen[nr][nc]:
                                    seen[nr][nc]=True; stack.append((nr,nc))
                    k+=1
        return cid
    cid=comp_id(); dirs={}
    for i in range(h):
        for j in range(w):
            if g[i][j]==2:
                diag=[(i+di,j+dj) for di in(-1,1) for dj in(-1,1) if 0<=i+di<h and 0<=j+dj<w and g[i+di][j+dj]==2]
                if diag:
                    cols={c for _,c in diag}; rows={r for r,_ in diag}
                    if len(cols)==1: dirs[(i,j)]=(0,1) if next(iter(cols))<j else (0,-1)
                    elif len(rows)==1: dirs[(i,j)]=(1,0) if next(iter(rows))<i else (-1,0)
    out=[r[:] for r in g]; ts=list(dirs)
    for a in range(len(ts)):
        for b in range(a+1,len(ts)):
            p,q=ts[a],ts[b]
            if cid[p[0]][p[1]]==cid[q[0]][q[1]] or dirs[p]!=(-dirs[q][0],-dirs[q][1]): continue
