    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or out[i][j] == bg:
                continue
            c = out[i][j]
            comp = [(i, j)]
            stack = [(i, j)]
            seen[i][j] = True
            while stack:
